-- TASK-0065 Open Hand teaching items: ap-calculus-ab (5 items). Generated by
-- scripts/content-seed/task0065_load/build_load_sql.py. Idempotent: re-running
-- skips content_keys already present in the target pack.
do $oht0065$
declare
  v_subject text := 'ap-calculus-ab';
  v_tsv uuid := '33b4408b-0ecc-4c7a-b0b1-612db81164a1';
  v_owner uuid := (select p.user_id from app.profiles p where p.user_id = 'f5a26c6b-3566-4d58-9e97-979fbb947564');
  v_items jsonb := $oht0065json$[{"content_key":"apcalcab-oht-1.2","topic_code":"1.2","title":"Defining Limits and Using Limit Notation","stem":"Let f be a function. Which statement is the correct reading of the notation lim as x→4+ of f(x) = 9?","choices":[{"choice_key":"A","choice_text":"When x = 4, f(x) equals 9.","is_correct":false,"rationale":"Tempting if you read lim f(x) = 9 as 'plug x = 4 into f and get 9' — but a limit describes the values f(x) approach as x nears 4, and f(4) may differ from 9 or not exist at all. Fix: read the notation aloud as 'f(x) approaches 9 as x approaches 4 from the right' before matching it to a choice."},{"choice_key":"B","choice_text":"As x gets close to 4 through values greater than 4, f(x) gets close to 9.","is_correct":true,"rationale":"Earns the point: the plus sign marks a right-hand approach (x > 4), and the limit value 9 describes what f(x) approaches, without saying anything about f(4)."},{"choice_key":"C","choice_text":"As x gets close to 4 through values less than 4, f(x) gets close to 9.","is_correct":false,"rationale":"Tempting if you swap the meaning of the superscript and read 4+ as 'coming toward 4 from below' — but the + means x takes values greater than 4, so x approaches from the right. Fix: rewrite x→4+ as 'x > 4 and x getting closer to 4' before choosing."},{"choice_key":"D","choice_text":"As x gets close to 9, f(x) gets close to 4 from the right.","is_correct":false,"rationale":"Tempting if you swap input and output, treating 9 as the x-value approached and 4 as the output — but the number after the arrow under 'lim' is the x-value approached, and the number after '=' is the value f(x) approaches. Fix: label the number under 'lim' as the x-value and the number after '=' as the y-value before reading the statement."}]},{"content_key":"apcalcab-oht-1.11","topic_code":"1.11","title":"Defining Continuity at a Point","stem":"Let g(x) = (x^2 - 16)/(x - 4) for x ≠ 4, and g(4) = 6. Which statement about g at x = 4 is correct?","choices":[{"choice_key":"A","choice_text":"g is continuous at x = 4, because g(4) is defined and the limit exists.","is_correct":false,"rationale":"Tempting if you check only the first two conditions (g(4) exists and the limit exists) and stop there — but continuity also needs the limit to equal g(4), and 8 ≠ 6. Fix: compute both numbers, the limit (8) and g(4) (6), and compare them before concluding."},{"choice_key":"B","choice_text":"g is continuous at x = 4, because the graph is a connected line with no gap away from 4.","is_correct":false,"rationale":"Tempting if you judge continuity from how the graph looks away from x = 4, where it follows the line y = x + 4 — but at x = 4 that line has a hole at height 8 while the point g(4) sits at height 6. Fix: test continuity at the point itself by checking whether the limit as x→4 equals g(4)."},{"choice_key":"C","choice_text":"g is not continuous at x = 4, because the limit is 8 but g(4) = 6.","is_correct":true,"rationale":"Earns the point: canceling x - 4 gives x + 4, so the limit as x→4 is 8, while g(4) = 6. Continuity requires the limit to equal the function value, and 8 ≠ 6, so that condition fails."},{"choice_key":"D","choice_text":"g is not continuous at x = 4, because the limit does not exist when the denominator is 0.","is_correct":false,"rationale":"Tempting if you see the denominator x - 4 equal 0 at x = 4 and conclude the limit cannot exist — but the numerator is also 0 there, and the common factor x - 4 cancels, leaving x + 4 with limit 8. Fix: factor x^2 - 16 as (x - 4)(x + 4) and cancel before deciding whether a limit exists."}]},{"content_key":"apcalcab-oht-1.12","topic_code":"1.12","title":"Confirming Continuity over an Interval","stem":"Let f(x) = (x + 2)/(x^2 - 4x - 5). On which interval is f continuous?","choices":[{"choice_key":"A","choice_text":"[0, 5]","is_correct":false,"rationale":"Tempting if you find the trouble values but treat a closed endpoint as safe, as if continuity on [0, 5] only concerned the inside of the interval — but the bracket includes x = 5, where the denominator is 0 and f is undefined. Fix: list the excluded values (x = 5 and x = -1) and check each one against the interval, endpoints included."},{"choice_key":"B","choice_text":"[-2, 3]","is_correct":false,"rationale":"Tempting if you set the numerator x + 2 equal to 0 and treat x = -2 as the only trouble spot, so starting the interval at -2 seems safe — but discontinuities come from zeros of the denominator, and x = -1 lies inside [-2, 3]. Fix: factor the denominator, solve (x - 5)(x + 1) = 0, and check those x-values against the interval."},{"choice_key":"C","choice_text":"All real numbers, because f is a rational function.","is_correct":false,"rationale":"Tempting if you remember 'rational functions are continuous' and drop the 'on their domain' part — but f is undefined where the denominator is 0, at x = 5 and x = -1. Fix: factor the denominator and remove its zeros before naming any interval of continuity."},{"choice_key":"D","choice_text":"[0, 4]","is_correct":true,"rationale":"Earns the point: the denominator factors as (x - 5)(x + 1), so f fails only at x = 5 and x = -1. The interval [0, 4] avoids both."}]},{"content_key":"apcalcab-oht-1.13","topic_code":"1.13","title":"Removing Discontinuities","stem":"Let f(x) = (x^2 + x - 12)/(x - 3) for x ≠ 3, and f(3) = k. For what value of k is f continuous at x = 3?","choices":[{"choice_key":"A","choice_text":"7","is_correct":true,"rationale":"Earns the point: factor x^2 + x - 12 = (x + 4)(x - 3), cancel x - 3, and the limit is 3 + 4 = 7. Setting k equal to that limit removes the discontinuity."},{"choice_key":"B","choice_text":"0","is_correct":false,"rationale":"Tempting if you substitute x = 3 into the numerator only, get 0, and take that as the value — but the denominator is also 0, so the form 0/0 is indeterminate and does not give the limit. Fix: when substitution gives 0/0, factor and cancel, then substitute x = 3 into the simplified expression."},{"choice_key":"C","choice_text":"3","is_correct":false,"rationale":"Tempting if you set k equal to the x-value where the trouble occurs — but k is the output f(3), and it must equal the limit of f(x) as x→3, which is 7. Fix: compute the limit of f(x) as x→3 first, then set k equal to that number."},{"choice_key":"D","choice_text":"-4","is_correct":false,"rationale":"Tempting if, after factoring into (x + 4)(x - 3), you solve x + 4 = 0 as if you were finding zeros — but continuity needs the value that x + 4 approaches at x = 3, not where it equals zero. Fix: after canceling x - 3, substitute x = 3 into x + 4 to get the limit."}]},{"content_key":"apcalcab-oht-1.16","topic_code":"1.16","title":"Working with the Intermediate Value Theorem","stem":"The function f is continuous on [2, 8], with f(2) = 3 and f(8) = 11. Which conclusion is guaranteed?","choices":[{"choice_key":"A","choice_text":"There is at least one c in (2, 8) with f(c) = 1.","is_correct":false,"rationale":"Tempting if you picture f dipping below 3 before climbing to 11 and treat that possible dip as guaranteed — but f could rise steadily from 3 to 11 and never reach 1; the theorem only guarantees outputs between f(2) = 3 and f(8) = 11. Fix: before choosing, check that the target value lies between f(2) and f(8)."},{"choice_key":"B","choice_text":"There is at least one c in (2, 8) with f(c) = 12.","is_correct":false,"rationale":"Tempting if you picture f overshooting 11 and coming back down to f(8) = 11, and treat that possible overshoot as guaranteed — but f could stay at or below 11 the whole time, so 12 is never guaranteed. Fix: write down the guaranteed output interval [3, 11] and reject any target outside it."},{"choice_key":"C","choice_text":"No value is guaranteed, because f is not known to be differentiable.","is_correct":false,"rationale":"Tempting if you mix up the Intermediate Value Theorem with the Mean Value Theorem, which does require differentiability — but the Intermediate Value Theorem needs only continuity on the closed interval, and that is given. Fix: list the hypotheses of the theorem you are using (here, continuity on [2, 8]) and check only those."},{"choice_key":"D","choice_text":"There is at least one c in (2, 8) with f(c) = 7.","is_correct":true,"rationale":"Earns the point: f is continuous on [2, 8] and 7 lies strictly between f(2) = 3 and f(8) = 11, so the Intermediate Value Theorem guarantees such a c."}]}]$oht0065json$::jsonb;
  v_pv uuid; v_npv int;
  r jsonb; c jsonb;
  v_ci uuid; v_civ uuid; v_key text; v_correct text;
  v_loaded int := 0; v_skipped int := 0; v_released int := 0;
begin
  select count(*) into v_npv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null;
  if v_npv = 0 then
    raise exception 'task0065: no published, non-retired exam pack version for %', v_subject;
  end if;
  -- Prefer the published pack that already holds teaching items (two exist for
  -- Statistics in Development); otherwise require exactly one.
  select epv.id into v_pv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null
    and (v_npv = 1 or exists (select 1 from app.open_hand_teaching_items t
                              join app.content_items ci on ci.id = t.content_item_id
                              where ci.exam_pack_version_id = epv.id))
  order by (select count(*) from app.open_hand_teaching_items t join app.content_items ci on ci.id = t.content_item_id
            where ci.exam_pack_version_id = epv.id) desc, epv.id
  limit 1;
  if v_pv is null then
    raise exception 'task0065: % has % published packs and none holds teaching items; pick one explicitly', v_subject, v_npv;
  end if;

  for r in select * from jsonb_array_elements(v_items) loop
    v_key := r->>'content_key';
    if exists (select 1 from app.content_items where exam_pack_version_id = v_pv and content_key = v_key) then
      v_skipped := v_skipped + 1;
      continue;
    end if;
    if jsonb_array_length(r->'choices') <> 4
       or (select count(*) from jsonb_array_elements(r->'choices') x where (x->>'is_correct')::boolean) <> 1 then
      raise exception 'task0065: % must have 4 choices with exactly one correct', v_key;
    end if;
    if not exists (select 1 from app.taxonomy_topics tt where tt.taxonomy_source_version = v_tsv
                   and tt.topic_code = r->>'topic_code') then
      raise exception 'task0065: topic % not in taxonomy %', r->>'topic_code', v_tsv;
    end if;
    select x->>'choice_key' into v_correct from jsonb_array_elements(r->'choices') x
    where (x->>'is_correct')::boolean;

    insert into app.content_items (exam_pack_version_id, content_key, item_type, title, status)
    values (v_pv, v_key, 'mcq', r->>'title', 'draft')
    returning id into v_ci;

    insert into app.content_item_versions (content_item_id, version_num, stem, content_hash, status,
      review_status, rubric_type, evaluator_strategy, canonical_answer_1)
    values (v_ci, 1, r->>'stem', md5(v_key), 'draft', 'tutor_review_pending', 'mcq', 'rule_based_mcq', v_correct)
    returning id into v_civ;

    for c in select * from jsonb_array_elements(r->'choices') loop
      insert into app.mcq_choices (content_item_version_id, choice_key, choice_text, is_correct, rationale)
      values (v_civ, c->>'choice_key', c->>'choice_text', (c->>'is_correct')::boolean, c->>'rationale');
    end loop;

    insert into app.content_item_cells (content_item_version_id, content_item_id, taxonomy_source_version,
      topic_code, skill_code, is_primary, assignment_status, source, model_run_id)
    values (v_civ, v_ci, v_tsv, r->>'topic_code', null, true, 'authored', 'task0065_oht_generated_2026_10_06',
      'TASK-0065 Open Hand teaching batch 2026-10-06 (authored to this topic; checked per CHECK_RESULTS.md)');

    -- Publish gates: enforce_publish_gate (approved review_status),
    -- tg_content_pipeline_guard_publish (published only from reviewed_approved),
    -- enforce_mcq_stem_choice_sync (runs on publish; choices exist by now).
    update app.content_item_versions set status = 'reviewed_approved', review_status = 'question_review_approved',
      approved_by = v_owner, approved_at = now() where id = v_civ;
    update app.content_item_versions set status = 'published', published_at = now() where id = v_civ;
    update app.content_items set status = 'reviewed_approved' where id = v_ci;
    update app.content_items set status = 'published' where id = v_ci;

    insert into app.open_hand_teaching_items (content_item_id, topic_code, source, note)
    values (v_ci, r->>'topic_code', 'generated', 'TASK-0065 batch 2026-10-06')
    on conflict (content_item_id) do nothing;
    v_loaded := v_loaded + 1;
  end loop;

  -- Return superseded spares (same subject + topic) to scoring.
  with rel as (
    update app.open_hand_teaching_items t set released_at = now()
    from app.content_items ci, app.exam_pack_versions epv, app.exam_packs ep, app.subjects s
    where ci.id = t.content_item_id and epv.id = ci.exam_pack_version_id and ep.id = epv.exam_pack_id
      and s.id = ep.subject_id and s.subject_key = v_subject
      and t.source = 'spare' and t.released_at is null
      and exists (select 1 from app.open_hand_teaching_items g
                  join app.content_items gci on gci.id = g.content_item_id
                  where g.source = 'generated' and g.released_at is null and g.note = 'TASK-0065 batch 2026-10-06'
                    and g.topic_code = t.topic_code and gci.exam_pack_version_id = v_pv
                    and gci.status = 'published')
    returning t.content_item_id)
  select count(*) into v_released from rel;

  raise notice 'task0065 %: pack %, loaded %, skipped %, spares released %', v_subject, v_pv, v_loaded, v_skipped, v_released;
end
$oht0065$;
